import jakarta.validation.constraints.*;
import jakarta.ws.rs.core.*;
import jakarta.transaction.Transactional;
import java.util.*;

record CreateOrder(@NotBlank(message = "itemは必須です") String item, @Min(value = 1, message = "countは1以上です") int count) { }

record OrderDto(long id, String item, int count) { }

record ApiError(String code, Object detail) { }

class OrderService {
    private final Map<String, Integer> stock = new HashMap<>(Map.of("book", 3, "pen", 1));

    @Transactional
    Response create(String caller, String role, CreateOrder in) {
        List<String> errors = MiniValidator.validate(in);
        if (!errors.isEmpty()) return Response.status(400).entity(new ApiError("VALIDATION_ERROR", errors)).build();
        if (caller.isEmpty()) return Response.status(401).entity(new ApiError("UNAUTHENTICATED", "ログインが必要です")).build();
        if (!role.equals("admin") && !role.equals("member")) return Response.status(403).entity(new ApiError("FORBIDDEN", "権限がありません")).build();
        Integer current = stock.get(in.item());
        if (current == null) return Response.status(404).entity(new ApiError("NOT_FOUND", "商品がありません")).build();
        if (current < in.count()) return Response.status(409).entity(new ApiError("OUT_OF_STOCK", "在庫が足りません")).build();
        stock.put(in.item(), current - in.count());
        return Response.status(201).entity(new OrderDto(1, in.item(), in.count())).build();
    }
}

public class OrderApiWithAuth {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        String caller = sc.next();
        if (caller.equals("_")) caller = "";
        String role = sc.next();
        String item = sc.next();
        if (item.equals("_")) item = "";
        CreateOrder in = new CreateOrder(item, sc.nextInt());
        Response r = new OrderService().create(caller, role, in);
        System.out.println(r.getStatus() + " " + r.getEntity());
    }
}
